public class InnerDeliveryStreamDatabaseSourceConfigurationFactory(Action<Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration>
{

    internal InnerDeliveryStreamDatabaseColumnsFactory ColumnsFactory { get; set; }

    internal InnerDeliveryStreamDatabasesFactory DatabasesFactory { get; set; }

    internal InnerDeliveryStreamDatabaseSourceAuthenticationConfigurationFactory DatabaseSourceAuthenticationConfigurationFactory { get; set; }

    internal InnerDeliveryStreamDatabaseTablesFactory TablesFactory { get; set; }

    internal InnerDeliveryStreamDatabaseSourceVPCConfigurationFactory DatabaseSourceVPCConfigurationFactory { get; set; }

    protected override Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration Create()
    {
        var databaseSourceConfigurationResult = CreateDatabaseSourceConfiguration();
        factoryAction?.Invoke(databaseSourceConfigurationResult);

        return databaseSourceConfigurationResult;
    }

    private Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration CreateDatabaseSourceConfiguration()
    {
        var databaseSourceConfigurationResult = new Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration();

        return databaseSourceConfigurationResult;
    }
    public override void CreateChildren(Humidifier.KinesisFirehose.DeliveryStreamTypes.DatabaseSourceConfiguration result)
    {
        base.CreateChildren(result);

        result.Columns ??= ColumnsFactory?.Build();
        result.Databases ??= DatabasesFactory?.Build();
        result.DatabaseSourceAuthenticationConfiguration ??= DatabaseSourceAuthenticationConfigurationFactory?.Build();
        result.Tables ??= TablesFactory?.Build();
        result.DatabaseSourceVPCConfiguration ??= DatabaseSourceVPCConfigurationFactory?.Build();
    }

} // End Of Class

